import pandas as pd

def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    events = inputs["cdc_events"].copy()

    # Build watermark lookup per device
    watermark = target.set_index("device_id")["applied_event_ts"].to_dict()

    def survives(row):
        wm = watermark.get(row["device_id"], None)
        if wm is None:
            return True
        return row["event_ts"] > wm

    if len(events) > 0:
        mask = events.apply(survives, axis=1)
        surviving = events[mask].copy()
    else:
        surviving = events.copy()

    if len(surviving) > 0:
        surviving = surviving.sort_values(
            by=["event_ts", "event_seq"], ascending=[True, True]
        )
        winners = surviving.groupby("device_id", as_index=False).tail(1)
    else:
        winners = surviving.copy()

    winners_map = winners.set_index("device_id")[["reading", "event_ts"]].to_dict("index")

    result_rows = []

    # Update existing devices
    for _, row in target.iterrows():
        dev = row["device_id"]
        if dev in winners_map:
            w = winners_map[dev]
            result_rows.append({
                "device_id": dev,
                "reading": w["reading"],
                "applied_event_ts": w["event_ts"],
            })
        else:
            result_rows.append({
                "device_id": dev,
                "reading": row["reading"],
                "applied_event_ts": row["applied_event_ts"],
            })

    existing_devices = set(target["device_id"].tolist())

    # New devices
    for dev, w in winners_map.items():
        if dev not in existing_devices:
            result_rows.append({
                "device_id": dev,
                "reading": w["reading"],
                "applied_event_ts": w["event_ts"],
            })

    new_snapshot = pd.DataFrame(
        result_rows, columns=["device_id", "reading", "applied_event_ts"]
    )

    new_snapshot["device_id"] = new_snapshot["device_id"].astype("int64")
    new_snapshot["reading"] = new_snapshot["reading"].astype("float64")
    new_snapshot["applied_event_ts"] = pd.to_datetime(
        new_snapshot["applied_event_ts"]
    ).astype("datetime64[us]")

    return {"new_snapshot": new_snapshot}
